-- Kalite planı, gereklilik matrisi, uygunsuzluk, kök neden, düzeltici faaliyet, kontrol noktası, cihaz, test, kabul, açık iş, çalışma izni belgesi; tedarik siparişi, malzeme kabulü, üçlü eşleştirme.
ALTER TABLE is_emri ADD COLUMN IF NOT EXISTS calisma_izni_gerekli boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS kabul_sinifi text CHECK (kabul_sinifi IN ('A', 'B', 'C', 'D'));
CREATE TABLE kalite_plani (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), dosya_ref uuid NOT NULL REFERENCES dosya (kimlik), surum integer NOT NULL, kabul_sinifi text NOT NULL CHECK (kabul_sinifi IN ('A', 'B', 'C', 'D')), ozet text NOT NULL, durum text NOT NULL DEFAULT 'Onay Bekliyor' CHECK (durum IN ('Onay Bekliyor', 'Onaylı', 'Reddedildi')), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now(), UNIQUE (dosya_ref, surum)
);
CREATE TABLE gereklilik_satiri (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_ref uuid NOT NULL REFERENCES kalite_plani (kimlik), gereklilik text NOT NULL, dogrulama text NOT NULL, kanit_belge_ref uuid REFERENCES belge (kimlik), durum text NOT NULL DEFAULT 'Açık' CHECK (durum IN ('Açık', 'Koşullu', 'Karşılandı'))
);
CREATE TABLE uygunsuzluk (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), uygunsuzluk_no text NOT NULL UNIQUE, dosya_ref uuid NOT NULL REFERENCES dosya (kimlik), is_emri_ref uuid REFERENCES is_emri (kimlik), tespit_kaynagi text NOT NULL, yer_nitelik text NOT NULL, dayanak_olcut text NOT NULL, gercek_durum text NOT NULL, kanit_belge_ref uuid NOT NULL REFERENCES belge (kimlik),
  sinif text NOT NULL CHECK (sinif IN ('Kritik', 'Majör', 'Minör', 'Gözlem')), yaygin_isareti boolean NOT NULL DEFAULT false, emniyet_isareti boolean NOT NULL DEFAULT false, hedef_zamani timestamptz, is_durduruldu boolean NOT NULL DEFAULT false, sorumlu_firma_ref uuid REFERENCES kurulus (kimlik),
  tasarruf_karari text CHECK (tasarruf_karari IN ('Olduğu Gibi Kabul', 'Düzeltme', 'Yeniden İşleme', 'Ayırma/Karantina', 'İade/Değişim', 'Ret/Hurda')), tasarruf_onaylayan_ref text REFERENCES kullanici_hesabi (kimlik), bedel_sorumlusu text CHECK (bedel_sorumlusu IN ('İş Birliği Firması', 'Tedarikçi', 'LİMİT GLOBAL MARINE')),
  firma_yeni_hasar boolean NOT NULL DEFAULT false, sorumluluk_ihbar_tarihi date, mahsup_referansi text, firma_yaniti text, yeniden_kontrol_sonucu text CHECK (yeniden_kontrol_sonucu IN ('Uygun', 'Koşullu uygun', 'Ek düzeltme', 'Ret')), kapanis_kaniti_ref uuid REFERENCES belge (kimlik), kapanis_yetkilisi_ref text REFERENCES kullanici_hesabi (kimlik), kok_neden_ref uuid,
  statu text NOT NULL DEFAULT 'Açık' CHECK (statu IN ('Açık', 'İşlemde', 'Doğrulamada', 'Kapalı', 'Geçersiz')), acan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now(), kapanis_zamani timestamptz
);
CREATE INDEX uygunsuzluk_dosya ON uygunsuzluk (dosya_ref, statu);
CREATE TABLE kok_neden_analizi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), uygunsuzluk_ref uuid NOT NULL REFERENCES uygunsuzluk (kimlik), problem_tanimi text NOT NULL, dogrudan_neden text NOT NULL, katki_faktorleri text NOT NULL, bariyer_analizi text NOT NULL, kok_neden text NOT NULL, tekrar_olasiligi text NOT NULL, analist_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE duzeltici_faaliyet (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), eylem_no text NOT NULL UNIQUE, kok_neden_ref uuid NOT NULL REFERENCES kok_neden_analizi (kimlik), eylem_turu text NOT NULL CHECK (eylem_turu IN ('Düzeltme', 'Düzeltici faaliyet', 'Önleyici faaliyet')), aciklama text NOT NULL, sorumlu_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), hedef_tarih date NOT NULL, etkinlik_gostergesi text NOT NULL, izleme_gun integer NOT NULL, tamamlanma_kaniti_ref uuid REFERENCES belge (kimlik), tamamlanma_tarihi date, etkinlik_sonucu text CHECK (etkinlik_sonucu IN ('Etkili', 'Etkisiz')), statu text NOT NULL DEFAULT 'Açık' CHECK (statu IN ('Açık', 'İşlemde', 'Doğrulamada', 'Kapalı', 'Geçersiz')), yeniden_acilma integer NOT NULL DEFAULT 0
);
CREATE TABLE kontrol_noktasi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), kontrol_noktasi_no text NOT NULL UNIQUE, is_emri_ref uuid NOT NULL REFERENCES is_emri (kimlik), kalem text, nokta_turu text NOT NULL CHECK (nokta_turu IN ('Bekletme', 'Tanıklık', 'Belge İnceleme', 'Gözetim', 'Uygulayıcı Öz Kontrolü', 'Bağımsız Doğrulama')), kontrol_ozelligi text NOT NULL, kabul_olcutu text NOT NULL, planlanan_zaman timestamptz NOT NULL, davet_zamani timestamptz NOT NULL DEFAULT now(), eksper_klas boolean NOT NULL DEFAULT false, katilim_durumu text CHECK (katilim_durumu IN ('Katıldı', 'Feragat', 'Ertelendi', 'Katılmadı – kanıtla ilerlendi')), sonuc text CHECK (sonuc IN ('Uygun', 'Koşullu uygun', 'Düzeltme gerekli', 'Reddedildi')), onaylar jsonb NOT NULL DEFAULT '[]', serbest_birakma_zamani timestamptz, kanit_belge_ref uuid REFERENCES belge (kimlik), uygunsuzluk_ref uuid REFERENCES uygunsuzluk (kimlik), olusturan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE olcum_cihazi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), ad text NOT NULL, seri_no text NOT NULL UNIQUE, kalibrasyon_tarihi date NOT NULL, aralik_ay integer NOT NULL DEFAULT 12 CHECK (aralik_ay > 0), kabul boolean NOT NULL DEFAULT true, kaydeden_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik)
);
CREATE TABLE test_kaydi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), test_no text NOT NULL UNIQUE, dosya_ref uuid NOT NULL REFERENCES dosya (kimlik), onceki_test_ref uuid REFERENCES test_kaydi (kimlik), test_grubu text NOT NULL, amac_kapsam text NOT NULL, yontem text NOT NULL, kabul_olcutu text NOT NULL, durdurma_kosulu text NOT NULL, cihazlar uuid[] NOT NULL DEFAULT '{}', ham_veri_ref uuid REFERENCES belge (kimlik), durdurma_olayi text, gozlemler text, sonuc text CHECK (sonuc IN ('Başarılı', 'Koşullu', 'Başarısız', 'Geçersiz', 'Engellendi')), sonuc_gerekcesi text, durum text NOT NULL DEFAULT 'Planlandı' CHECK (durum IN ('Planlandı', 'Kontrolde', 'Kararda', 'Tamamlandı')), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), kontrol_eden_ref text REFERENCES kullanici_hesabi (kimlik), karar_veren_ref text REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE kabul_kaydi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), dosya_ref uuid NOT NULL REFERENCES dosya (kimlik), is_emri_ref uuid REFERENCES is_emri (kimlik), kabul_turu text NOT NULL CHECK (kabul_turu IN ('Paket Kabulü', 'Teknik Kabul', 'Koşullu Kabul', 'Nihai Kabul', 'Ret')), kosul_bitis date, uzatildi boolean NOT NULL DEFAULT false, garanti_baslangic date, kaydeden_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE acik_is_kalemi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), kabul_ref uuid NOT NULL REFERENCES kabul_kaydi (kimlik), is_emri_ref uuid REFERENCES is_emri (kimlik), tanim text NOT NULL, etki text NOT NULL, hedef_tarih date NOT NULL, kapanis_kaniti_ref uuid REFERENCES belge (kimlik), kapanis_zamani timestamptz, gecikti boolean NOT NULL DEFAULT false
);
CREATE TABLE calisma_izni_belgesi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), is_emri_ref uuid NOT NULL REFERENCES is_emri (kimlik), izin_turu text NOT NULL, tesis text NOT NULL, izin_no text NOT NULL, izni_veren text NOT NULL, baslangic timestamptz NOT NULL, bitis timestamptz NOT NULL, belge_ref uuid NOT NULL REFERENCES belge (kimlik), oksijen_yuzde numeric(5,2), yanici_gaz_yuzde numeric(5,2), yangin_gozetim_dk integer, kapanis_zamani timestamptz, yukleyen_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now(), CHECK (bitis > baslangic)
);
CREATE TABLE tedarik_siparisi (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), siparis_no text NOT NULL UNIQUE, surum_no integer NOT NULL DEFAULT 1, dosya_ref uuid NOT NULL REFERENCES dosya (kimlik), kurulus_ref uuid NOT NULL REFERENCES kurulus (kimlik), tedarikci_teklif_ref text NOT NULL, nihai_kullanim_yeri text NOT NULL, kdv_haric_eur numeric(14,2) NOT NULL, kdv_eur numeric(14,2) NOT NULL, toplam_eur numeric(14,2) NOT NULL, teslim_tarihi date NOT NULL, teslim_yeri text NOT NULL, kismi_teslim_izni boolean NOT NULL DEFAULT false, kabul_olcutu text NOT NULL, secim_gerekcesi text NOT NULL, statu text NOT NULL DEFAULT 'Onay Bekliyor' CHECK (statu IN ('Taslak', 'Onay Bekliyor', 'Verildi', 'Kısmi Teslim', 'Teslim Alındı', 'Kapalı', 'İptal')), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tedarik_siparisi_kalemi (
  siparis_ref uuid NOT NULL REFERENCES tedarik_siparisi (kimlik), satir_no integer NOT NULL, urun_tanimi text NOT NULL, uretici_parca_no text NOT NULL, miktar numeric(14,3) NOT NULL CHECK (miktar > 0), birim text NOT NULL, birim_bedel_eur numeric(14,2) NOT NULL CHECK (birim_bedel_eur >= 0), toplam_eur numeric(14,2) NOT NULL, teslim_alinan numeric(14,3) NOT NULL DEFAULT 0, PRIMARY KEY (siparis_ref, satir_no)
);
CREATE TABLE malzeme_giris_kabulu (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), kayit_no text NOT NULL UNIQUE, siparis_ref uuid NOT NULL REFERENCES tedarik_siparisi (kimlik), satir_no integer NOT NULL, miktar numeric(14,3) NOT NULL CHECK (miktar > 0), lot_no text NOT NULL, irsaliye_no text NOT NULL, bekletme_yeri_ref uuid NOT NULL REFERENCES kurulus (kimlik), bekletme_baslangic timestamptz NOT NULL DEFAULT now(), kontrol_eden_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), kabul_karari text CHECK (kabul_karari IN ('Kabul', 'Koşullu Kabul', 'Karantina', 'Ret', 'İade Edildi')), uygunsuzluk_ref uuid REFERENCES uygunsuzluk (kimlik), hazirlayan_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), onay_zamani timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE uclu_eslestirme (
  kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), siparis_ref uuid NOT NULL REFERENCES tedarik_siparisi (kimlik), kurulus_ref uuid NOT NULL REFERENCES kurulus (kimlik), fatura_no text NOT NULL, fatura_tarihi date NOT NULL, fatura_tutari numeric(14,2) NOT NULL, miktar_farki numeric(14,3) NOT NULL, fiyat_farki numeric(14,2) NOT NULL, sonuc text NOT NULL CHECK (sonuc IN ('Eşleşti', 'Miktar Farkı', 'Fiyat Farkı', 'Fazla Teslim')), kontrol_eden_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), olusturma_zamani timestamptz NOT NULL DEFAULT now(), UNIQUE (kurulus_ref, fatura_no, fatura_tutari)
);
GRANT SELECT, INSERT, UPDATE ON kalite_plani, gereklilik_satiri, uygunsuzluk, kok_neden_analizi, duzeltici_faaliyet, kontrol_noktasi, olcum_cihazi, test_kaydi, kabul_kaydi, acik_is_kalemi, calisma_izni_belgesi, tedarik_siparisi, tedarik_siparisi_kalemi, malzeme_giris_kabulu, uclu_eslestirme TO yatonet_uygulama;
